def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        bid = min(budget, DAILY_SALARY * 0.35)
        if hp <= 2 or no_water >= 1:
            bid = min(budget, DAILY_SALARY * 0.75)
        return max(0, bid)

    prev_bids = []
    pressured_opponents = 0
    desperate_opponents = 0
    for opp in alive_opponents:
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            pressured_opponents += 1
        if opp.get('hp', 10) <= 1 or opp.get('no_water_days', 0) >= 2:
            desperate_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None and prev.get('error') in (None, '', False):
            prev_bids.append(prev.get('bid'))

    tight_supply = supply <= 17
    abundant_supply = supply >= 22

    if hp <= 1 or no_water >= 2:
        base = DAILY_SALARY * 0.96
    elif hp <= 2 or no_water >= 1:
        base = DAILY_SALARY * 0.82
    elif tight_supply:
        base = DAILY_SALARY * 0.62
    elif abundant_supply:
        base = DAILY_SALARY * 0.42
    else:
        base = DAILY_SALARY * 0.52

    if pressured_opponents >= 2:
        base += 5
    elif desperate_opponents == 0 and abundant_supply:
        base -= 4

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
        if highest_prev >= DAILY_SALARY * 0.9:
            if hp >= 4 and no_water == 0:
                bid = DAILY_SALARY * 0.28
            else:
                bid = DAILY_SALARY * 0.93
        elif highest_prev >= DAILY_SALARY * 0.7:
            if tight_supply or hp <= 3 or no_water >= 1:
                bid = min(DAILY_SALARY * 0.9, highest_prev + 2)
            else:
                bid = max(base, avg_prev + 1)
        else:
            bid = max(base, highest_prev + 1.5)
    else:
        bid = base

    if budget < DAILY_SALARY * 1.2:
        bid = min(bid, budget * 0.72)
    else:
        bid = min(bid, budget * 0.9)

    if hp >= 5 and no_water == 0 and abundant_supply and desperate_opponents == 0:
        bid = min(bid, DAILY_SALARY * 0.45)

    bid = max(0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        target = min(my_budget, DAILY_SALARY * 0.35)
        return float(target)

    # Read yesterday's immediate behavior
    prev_bids = []
    prev_high_pressure = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
            except Exception:
                continue
            prev_bids.append(b_val)
            if b_val > prev_high_pressure:
                prev_high_pressure = b_val

    # Baseline: bid enough to contest but avoid overpaying
    # Supply is between 15 and 25; typical number of 9-unit blocks is 1.
    # We bias toward securing at least one unit of requirement.
    # Convert supply to a rough “how many winners possible” estimate.
    # Use conservative scaling to avoid index issues.
    blocks = max(1.0, supply / float(WATER_REQ))
    contest_factor = 1.0 / blocks

    if prev_bids:
        high_thresh = DAILY_SALARY * 0.85
        mid_thresh = DAILY_SALARY * 0.6

        if prev_high_pressure >= high_thresh:
            # They were likely desperate; we should not lose the contest.
            if my_hp <= 2.0 or my_no_water_days >= 2:
                bid = DAILY_SALARY * 0.95
            else:
                bid = DAILY_SALARY * 0.45 + (prev_high_pressure * 0.35)
        elif prev_high_pressure >= mid_thresh:
            # Moderate pressure: bid slightly above a safe baseline.
            bid = DAILY_SALARY * 0.35 + (prev_high_pressure * 0.25)
        else:
            # They were not aggressive: bid near baseline and save budget.
            bid = DAILY_SALARY * 0.28
    else:
        # No trace info: use hp/budget and supply to decide.
        if my_hp <= 2.0 or my_no_water_days >= 2:
            bid = DAILY_SALARY * 0.8
        else:
            bid = DAILY_SALARY * (0.32 + 0.12 * contest_factor)

    # Clamp to budget and reasonable bounds
    bid = float(bid)
    if bid > my_budget:
        bid = my_budget

    # Additional clamp relative to supply: never bid more than what would be wasteful.
    # Since water is scarce, keep within 0.95*DAILY_SALARY.
    if bid > DAILY_SALARY * 0.95:
        bid = DAILY_SALARY * 0.95
    if bid < 0.0:
        bid = 0.0

    return float(bid)
